        const month = leftPad2(date.getMonth() + 1, 2);
        const day = leftPad2(date.getDate(), 2);
        const hours = leftPad2(date.getHours(), 2);
        const minutes = leftPad2(date.getMinutes(), 2);
        const seconds = leftPad2(date.getSeconds(), 2);
